# Simulator Parser Hierarki & Validasi Konfigurasi Proyek dbt
class DBTProjectManifestValidator:
    def __init__(self, project_name):
        self.project_name = project_name
        self.sources = {}
        self.models = {}

    def register_source(self, source_name, tables):
        self.sources[source_name] = tables

    def register_model(self, model_name, materialization, upstream_refs):
        self.models[model_name] = {
            'materialization': materialization,
            'refs': upstream_refs
        }

    def validate_integrity(self):
        errors = []
        # Validasi bahwa semua ref mengacu pada model atau source yang terdaftar
        all_known_entities = set(self.models.keys())
        for s_name, tables in self.sources.items():
            for t in tables:
                all_known_entities.add(f'{s_name}.{t}')

        for m_name, meta in self.models.items():
            for ref in meta['refs']:
                if ref not in all_known_entities:
                    errors.append(f"Model '{m_name}' mengacu pada entitas tidak dikenal: '{ref}'")

        return len(errors) == 0, errors

validator = DBTProjectManifestValidator('ecommerce_analytics')
validator.register_source('raw_postgres', ['orders', 'users'])
validator.register_model('stg_orders', 'view', ['raw_postgres.orders'])
validator.register_model('stg_users', 'view', ['raw_postgres.users'])
validator.register_model('fct_customer_churn', 'table', ['stg_orders', 'stg_users'])

is_valid, validation_errors = validator.validate_integrity()
print(f"Validasi Manifest Proyek dbt '{validator.project_name}':")
print(f"  Total Source Terdaftar : {len(validator.sources)}")
print(f"  Total Model Terdaftar  : {len(validator.models)}")
print(f"  Status Integritas Graf : {'PASSED (Valid)' if is_valid else 'FAILED'}")
print('Kesimpulan: Manifest dbt memvalidasi integritas relasi antar-entitas sebelum kompilasi SQL.')

# Simulator Pengambilan Keputusan Materialisasi Optimal dbt Berdasarkan Karakteristik Model
class MaterializationAdvisor:
    @staticmethod
    def recommend_strategy(row_count, read_frequency_per_day, transformation_complexity_score):
        # transformation_complexity_score: 1 (ringan/filter) s.d. 10 (banyak join & window)
        if transformation_complexity_score <= 2 and row_count < 100_000:
            return 'view', 'Dataset kecil & transformasi ringan: View hemat storage dan selalu up-to-date.'
        elif read_frequency_per_day > 20 and transformation_complexity_score >= 5 and row_count < 1_000_000:
            return 'table', 'Sering dibaca & komputasi berat: Table fisik mempercepat response time query.'
        elif row_count >= 1_000_000:
            return 'incremental', 'Dataset masif (>1M baris): Incremental menghemat biaya & komputasi rebuild.'
        else:
            return 'ephemeral', 'Model perantara ringan: Ephemeral mencegah polusi skema di warehouse.'

models_to_test = [
    ('stg_orders', 50_000, 5, 2),
    ('int_user_sessions', 300_000, 2, 4),
    ('mart_daily_revenue', 500_000, 150, 7),
    ('fct_ad_impressions', 25_000_000, 80, 8)
]

print('Rekomendasi Strategi Materialisasi dbt:')
for name, rows, reads, comp in models_to_test:
    strat, reason = MaterializationAdvisor.recommend_strategy(rows, reads, comp)
    print(f"  Model '{name}': Materialize as [{strat.upper()}]")
    print(f"    Alasan: {reason}")
print('Kesimpulan: Pemilihan materialisasi yang tepat menyeimbangkan biaya komputasi dan performa query.')

