# Simulator Engine Pengujian Kualitas Data Deklaratif dbt (Generic & Singular Tests)
class DBTDataTestEngine:
    @staticmethod
    def test_unique(dataset, column_name):
        values = [r[column_name] for r in dataset if column_name in r]
        duplicates = [v for v in set(values) if values.count(v) > 1]
        return len(duplicates) == 0, duplicates

    @staticmethod
    def test_not_null(dataset, column_name):
        null_rows = [r for r in dataset if r.get(column_name) is None]
        return len(null_rows) == 0, len(null_rows)

    @staticmethod
    def test_accepted_values(dataset, column_name, allowed_set):
        invalid_rows = [r for r in dataset if r.get(column_name) not in allowed_set]
        return len(invalid_rows) == 0, invalid_rows

test_table = [
    {'order_id': 1001, 'user_id': 50, 'status': 'PAID', 'amount': 250000},
    {'order_id': 1002, 'user_id': 51, 'status': 'PENDING', 'amount': 150000},
    {'order_id': 1003, 'user_id': None, 'status': 'REFUNDED', 'amount': 75000}, # Null user!
    {'order_id': 1001, 'user_id': 52, 'status': 'UNKNOWN', 'amount': 10000}   # Duplikat ID & status ilegal
]

is_u, dupes = DBTDataTestEngine.test_unique(test_table, 'order_id')
is_nn, null_count = DBTDataTestEngine.test_not_null(test_table, 'user_id')
is_av, invalid_vals = DBTDataTestEngine.test_accepted_values(test_table, 'status', {'PAID', 'PENDING', 'REFUNDED'})

print('Hasil Eksekusi dbt Data Test Suite:')
print(f"  Test 'unique(order_id)'          : {'PASS' if is_u else 'FAIL'} (Duplikat: {dupes})")
print(f"  Test 'not_null(user_id)'        : {'PASS' if is_nn else 'FAIL'} (Total NULL: {null_count})")
print(f"  Test 'accepted_values(status)'  : {'PASS' if is_av else 'FAIL'} (Nilai Ilegal: {[r['status'] for r in invalid_vals]})")
print('Kesimpulan: Asersi data dbt mendeteksi anomali data kotor sebelum merusak dashboard analitik.')

# Simulator Astronomer Cosmos: Mengonversi Manifest dbt Menjadi Task DAG Airflow
class CosmosManifestParser:
    @staticmethod
    def parse_manifest_to_airflow_tasks(dbt_manifest):
        airflow_tasks = {}
        for node_id, node_data in dbt_manifest['nodes'].items():
            model_name = node_data['name']
            # Ekstrak parent model dari depends_on
            upstream_models = [
                p.split('.')[-1] for p in node_data['depends_on']['nodes'] 
                if p.startswith('model.')
            ]
            airflow_tasks[model_name] = {
                'task_id': f'dbt_run_{model_name}',
                'operator': 'DbtRunOperator',
                'upstreams': upstream_models
            }
        return airflow_tasks

mock_dbt_manifest = {
    'nodes': {
        'model.ecommerce.stg_orders': {'name': 'stg_orders', 'depends_on': {'nodes': ['source.raw.orders']}},
        'model.ecommerce.stg_users': {'name': 'stg_users', 'depends_on': {'nodes': ['source.raw.users']}},
        'model.ecommerce.fct_daily_sales': {'name': 'fct_daily_sales', 'depends_on': {'nodes': ['model.ecommerce.stg_orders', 'model.ecommerce.stg_users']}}
    }
}

tasks = CosmosManifestParser.parse_manifest_to_airflow_tasks(mock_dbt_manifest)
print('Hasil Pemetaan Manifest dbt ke Airflow Task Graph (Cosmos Style):')
for m_name, meta in tasks.items():
    print(f"  Airflow Task: {meta['task_id']} | Upstream Dependensi: {meta['upstreams']}")
print('Kesimpulan: Pemetaan granular Cosmos memungkinkan observabilitas dan isolasi retry per-model.')

# Proyek Praktik: Simulator Lengkap Pipeline Transformasi Fitur RFM Churn dengan dbt Core
class ChurnFeatureStorePipeline:
    @staticmethod
    def run_staging(raw_transactions):
        # Step 1: Filter & Cast
        cleaned = []
        for t in raw_transactions:
            if t['status'] == 'COMPLETED' and t['amount'] > 0:
                cleaned.append(t)
        return cleaned

    @staticmethod
    def run_intermediate_rfm(cleaned_transactions, reference_day=100):
        # Step 2: Hitung Recency, Frequency, Monetary per user
        user_stats = {}
        for t in cleaned_transactions:
            u_id = t['user_id']
            if u_id not in user_stats:
                user_stats[u_id] = {'last_day': t['day'], 'count': 0, 'total_spend': 0}
            user_stats[u_id]['count'] += 1
            user_stats[u_id]['total_spend'] += t['amount']
            if t['day'] > user_stats[u_id]['last_day']:
                user_stats[u_id]['last_day'] = t['day']

        rfm_features = {}
        for u_id, s in user_stats.items():
            rfm_features[u_id] = {
                'user_id': u_id,
                'recency_days': reference_day - s['last_day'],
                'frequency_90d': s['count'],
                'monetary_idr': s['total_spend'],
                'avg_basket_idr': round(s['total_spend'] / s['count'], 2)
            }
        return rfm_features

raw_trx = [
    {'user_id': 'U101', 'day': 95, 'amount': 150000, 'status': 'COMPLETED'},
    {'user_id': 'U101', 'day': 98, 'amount': 250000, 'status': 'COMPLETED'},
    {'user_id': 'U102', 'day': 30, 'amount': 500000, 'status': 'COMPLETED'},
    {'user_id': 'U103', 'day': 99, 'amount': 0, 'status': 'FAILED'} # Diabaikan
]

stg = ChurnFeatureStorePipeline.run_staging(raw_trx)
features = ChurnFeatureStorePipeline.run_intermediate_rfm(stg, reference_day=100)

print('Eksekusi Proyek Praktik: Feature Store dbt untuk Prediksi Churn:')
for u_id, f in features.items():
    print(f"  User {u_id}: Recency={f['recency_days']} hari | Freq={f['frequency_90d']}x | Spend=Rp{f['monetary_idr']:,} | Avg=Rp{f['avg_basket_idr']:,}")
print('Kesimpulan: dbt menyajikan matriks fitur ML bersih, terstandarisasi, dan deterministik.')
